List<double> calculateStatistics(List<num> numbers) {
  if (numbers.isEmpty) {
    throw ArgumentError('The list of numbers cannot be empty.');
  }

  double sum = numbers.reduce((a, b) => a + b);
  double mean = sum / numbers.length;

  List<double> sortedNumbers = [...numbers].sortDouble(); 
  double median;
  int n = sortedNumbers.length;

  if (n % 2 == 1) {
    median = sortedNumbers[n ~/ 2];
  } else {
    median = (sortedNumbers[(n - 1) ~/ 2] + sortedNumbers[n ~/ 2]) / 2;
  }

  double min = sortedNumbers.first;
  double max = sortedNumbers.last;
  double range = max - min;

  double variance = numbers.map((num) => pow(num - mean, 2)).reduce((a, b) => a + b) / numbers.length;
  double standardDeviation = sqrt(variance);

  return [mean, median, min, max, range, standardDeviation];
}
