int carRaceCollision(int n) {
  if (n == 0 || n == 1) return 0;

  int count = 0;
  for (int i = 2; i <= n; i++) {
    List<int> cars = List.filled(i, 0);
    int collisions = 0;

    // Initialize positions and speeds
    for (int j = 0; j < i; j++) {
      cars[j] = Random().nextInt(50); // Position between 0-49
    }

    while (!isStable(cars)) {
      // Calculate next step based on speed rules
      for (int j = 0; j < i; j++) {
        if (j > 0 && cars[j - 1] != null) {
          double distanceToPrev = cars[j]! - cars[j - 1];
          if (distanceToPrev >= 3.0) {
            cars[j] = cars[j]! + 1;
          } else if (distanceToPrev == 0) {
            // Collision occurred at position cars[j]
            collisions++;
            break;
          } else if (distanceToPrev < 3.0) {
            // Car will catch up to previous one
            cars[j] = cars[j]! + 1;
          }
        }
      }

      // Check for collisions after moving all cars
      for (int j = 0; j < i - 1; j++) {
        if (cars[j] == cars[j + 1]) {
          collisions += 2;
          break;
        }
      }
    }

    count += collisions;
  }

  return count;
}

bool isStable(List<int>? cars) {
  if (cars == null || cars.isEmpty) return true;
  for (int i = 0; i < cars.length - 1; i++) {
    if (cars[i] == cars[i + 1]) {
      return false;
    }
  }
  return true;
}
