/// print(monotonic([3, 2, 1])); // true (non-increasing)
/// print(monotonic([5, 5, 5])); // true (constant)
/// print(monotonic([]));        // true (empty)
/// print(monotonic(null));      // true (null)
/// print(monotonic([1, 3, 2])); // false (not monotonic)
/// ```
bool monotonic(List<num> l) {
  if (l == null || l.isEmpty) return true;

  bool isNonDecreasing = true;
  bool isNonIncreasing = true;

  for (int i = 1; i < l.length; i++) {
    if (l[i] < l[i - 1]) {
      isNonDecreasing = false;
    } else if (l[i] > l[i - 1]) {
      isNonIncreasing = false;
    }
  }

  return isNonDecreasing || isNonIncreasing;
}
