List<num> derivative(List<num> xs) {
  if (xs.isEmpty || xs.length == 1) return [];

  final n = xs.length;
  List<num> result = List.filled(n - 1, 0.0);

  for (int i = 1; i < n; i++) {
    // Forward difference formula with central differences where possible
    num h = xs[i] - xs[i-1];

    if (i > 1 && i < n - 1) {
      // Central difference
      result[i - 1] = (xs[i+1] - xs[i-1]) / (2 * h);
    } else {
      // Forward or backward difference
      result[i - 1] = (xs[i] - xs[i-1])/h;
    }
  }

  return result;
}
