String circularShift(int x, int shift) {
  // Convert the integer to its binary string representation without '0b' prefix.
  String binaryStr = x.toRadixString(2);

  // Calculate the effective number of shifts needed modulo the length of the binary string.
  int effectiveShifts = (shift % binaryStr.length).abs();

  if (effectiveShifts == 0) {
    return binaryStr;
  }

  // Determine whether it's a left or right shift based on sign of shift.
  bool isLeftShift = shift > 0;

  int splitIndex = isLeftShift ? effectiveShifts : binaryStr.length - effectiveShifts;

  // Perform the circular shift.
  String shiftedBinary = isLeftShift 
      ? binaryStr.substring(splitIndex) + binaryStr.substring(0, splitIndex)
      : binaryStr.substring(splitIndex) + binaryStr.substring(0, splitIndex);

  // Convert back to integer and then to string with leading zeros as required.
  int resultInt = int.parse(shiftedBinary, radix: 2);
  return resultInt.toString(); // This will automatically handle leading zeros by returning the numeric value.
