List<int> generatePrimesUpTo(int limit) {
  if (limit < 2) return [];
  final sieve = List<bool>.filled(limit + 1, true);
  sieve[0] = false;
  sieve[1] = false;

  for (int i = 2; i * i <= limit; ++i) {
    if (sieve[i]) {
