  List<int> sorted = [...array];

  int n = sorted.length;

  for (int i = 0; i < n - 1; i++) {
    bool swapped = false;

    for (int j = 0; j < n - i - 1; j++) {
      if (sorted[j] > sorted[j + 1]) {
        // Swap elements if they are in the wrong order
        int temp = sorted[j];
        sorted[j] = sorted[j + 1];
        sorted[j + 1] = temp;
        swapped = true;
      }
    }

    // If no swaps occurred, the list is already sorted
    if (!swapped) break;
  }

  return sorted;
}
