      i++;
    }

    if (i >= s.length) break;

    String word = '';
    bool isDigitsOnly = true;

    while (i < s.length && RegExp(r'[A-Za-z0-9]').hasMatch(s[i])) {
      word += s[i];
      isDigitsOnly &= s[i].isDigit();
      i++;
    }

    if (word.isNotEmpty) {
      // Check for abbreviations like "U.S.A." -> should be split into ["U", ".", "S", "."]
      List<String> parts = [];
      int j = 0;

      while (j < word.length) {
        if (word[j] == '.') {
          parts.add('.');
          j++;
        } else if (word[j] == ',' || word[j] == '-' || word[j] == '_' || 
                  word[j] == '@' || word[j] == '#' || word[j] == '$') {
          parts.add(word[j]);
          j++;
        } else if (j + 1 < word.length && word[j+1] == '.' && word[j+2] == '.' &&
                   word[j+3] == '.' && j+3 < word.length) { // Handle ... in the middle of a word
          parts.add('...');
          j += 4; // skip three dots and the next character
        } else if (j + 1 < word.length && word[j+1] == '.' && j+1 < word.length - 1) {
          parts.add('.');
          j += 2;
        } else if (j + 1 < word.length && word[j+1] == '-') {
          parts.add(word.substring(j, j+2));
          j += 2;
        } else if (j + 1 < word.length && word[j+1] == '_') {
          parts.add(word.substring(j, j+2));
          j += 2;
        } else {
          parts.add(word[j]);
          j++;
        }
      }

      for (var part in parts) {
        if (part != '' && !part.contains(RegExp(r"[^a-zA-Z0-9.]"))) {
