int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Check for invalid input
  if (capacity < 1 || capacity > rows * cols) return -1;

  List<int> rowSums = List.filled(rows, 0);
  List<int> colSums = List.filled(cols, 0);

  for (var i = 0; i < rows; i++) {
    var sumRow = 0;
    for (var j = 0; j < cols; j++) {
      sumRow += grid[i][j];
    }
    rowSums[i] = sumRow;
  }

  for (var j = 0; j < cols; j++) {
    var sumCol = 0;
    for (var i = 0; i < rows; i++) {
      sumCol += grid[i][j];
    }
    colSums[j] = sumCol;
  }

  var totalSum = rowSums.reduce((a, b) => a + b);
  if (totalSum <= capacity) return totalSum;

  final Set<int> possibleRows = Set<int>.from(rowSums.where((sum) => sum >= 1));
  final Set<int> possibleCols = Set<int>.from(colSums.where((sum) => sum >= 1));

  while (possibleRows.isNotEmpty && possibleCols.isNotEmpty) {
    int selectedRow = possibleRows.first;
    int selectedCol = possibleCols.first;

    // Try to fill the cell at [selectedRow][selectedCol]
    final currentVal = grid[selectedRow][selectedCol];

    // Calculate how much we can add without exceeding the capacity and not overfilling either dimension
    final maxAdd = min(
        (capacity - totalSum),
        min(
          (rowSums[selectedRow] - currentVal),
          (colSums[selectedCol] - currentVal)));

    if (maxAdd == 0) {
      // No more space in this row or column. Remove from sets.
      possibleRows.remove(selectedRow);
      possibleCols.remove(selectedCol);
      continue;
    }

    // Add as much as possible
    grid[selectedRow][selectedCol] += maxAdd;
    totalSum += maxAdd;

    // Update the sums of the affected dimensions
    rowSums[selectedRow] = grid[selectedRow].reduce((a, b) => a + b);
    colSums[selectedCol] = grid.map((row) => row[selectedCol]).reduce((a, b) => a + b);
  }

  return totalSum;
