// It ensures that no row has more than [capacity] total value by moving values to adjacent cells when needed.
int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || capacity < 1) return 0;

  final cols = grid[0].length;
  final result = List.filled(rows, 0);

  for (var i = 0; i < rows; ++i) {
    var colIndex = 0;
    var remainingCapacityInRow = capacity;

    // Process each column in the current row from left to right
