List<int> maximum(List<int> arr, int k) {
  if (k == 0 || k >= arr.length) {
    return List.from(arr);
  }

  // Create a priority queue to keep track of the largest elements.
  PriorityQueue<int> pq = PriorityQueue<int>((a, b) => b.compareTo(a));

  for (int i = 0; i < arr.length && i <= k; i++) {
    pq.add(arr[i]);
  }

  for (int i = k; i < arr.length; i++) {
    int current = arr[i];
    if (current > pq.peek()) {
      pq.remove(pq.peek());
      pq.add(current);
    }
  }

  // Extract the top k elements from the priority queue and reverse them to get descending order.
  List<int> result = [];
  while (pq.isNotEmpty) {
    result.add(pq.removeFirst());
  }
  return result;
}
