import 'dart:math';

List<int> maximum(List<int> arr, int k) {
  if (arr.isEmpty || k == 0) return [];

  final n = arr.length;
  final maxHeap = List<int>.from(arr);
  heapify(maxHeap);

  for (int i = 1; i < k; ++i) {
    maxHeap[0] = maxHeap.removeLast();
    siftDown(maxHeap, 0, maxHeap.length - 1);
  }

  return [maxHeap[0]];
}

void heapify(List<int> heap) {
  final n = heap.length;
  for (int i = (n ~/ 2) - 1; i >= 0; --i) {
    siftDown(heap, i, n - 1);
  }
}

void siftDown(List<int> heap, int index, int bottom) {
  while (index * 2 + 1 <= bottom) {
    final leftChildIndex = index * 2 + 1;
    final rightChildIndex = index * 2 + 2;

    var largest = index;

    if (leftChildIndex <= bottom && heap[leftChildIndex] > heap[largest]) {
      largest = leftChildIndex;
    }

    if (rightChildIndex <= bottom && heap[rightChildIndex] > heap[largest]) {
      largest = rightChildIndex;
    }

    if (largest != index) {
      swap(heap, index, largest);
      index = largest;
    } else {
      break;
    }
  }
}

void swap(List<int> list, int a, int b) {
  final temp = list[a];
  list[a] = list[b];
  list[b] = temp;
}
