import 'dart:math';

int digits(int n) {
  // Handle the case of zero explicitly since log10(0) is undefined.
  if (n == 0) return 1;

  // Use logarithm to calculate the number of digits in a positive integer.
  // The formula is based on the fact that for any positive real x, floor(log10(x)) + 1 gives the number of digits.
  final digitCount = log10(n).floor() + 1;

  // Return the calculated digit count as an integer.
  return digitCount.toInt();
}

// Helper function to handle negative numbers by taking their absolute value first.
int absDigits(int n) {
  return digits(abs(n));
}
