String fileNameCheck(String fileName) {
  if (fileName.isEmpty) return 'Invalid file name';

  final extensions = ['txt', 'csv', 'json'];
  int lastDotIndex = fileName.lastIndexOf('.');

  if (lastDotIndex == -1 || lastDotIndex == 0) {
    return 'File must have an extension.';
  }

  String? ext;
  if (lastDotIndex < fileName.length - 1) {
    ext = fileName.substring(lastDotIndex + 1);
  } else {
    return 'Invalid file name format: missing extension.';
  }

  if (!extensions.contains(ext.toLowerCase())) {
    return "Unsupported file type. Supported types are: ${extensions.join(', ')}";
  }

  if (ext != null && !ext.startsWith('[')) {
    // Check for optional parameters in the filename, e.g., [name]
    final paramsStartIndex = fileName.indexOf('[');
    if (paramsStartIndex != -1) {
      var paramEndIndex = fileName.indexOf(']', paramsStartIndex);
      if (paramEndIndex != -1) {
        final parameterName = fileName.substring(paramsStartIndex + 1, paramEndIndex);

        if (parameterName.isNotEmpty) {
          final paramValue = fileName.split('?')[1] ?? '';
          final keyValuePairs = paramValue.split('&');

          bool validParam = false;
          for (var pair in keyValuePairs) {
            final parts = pair.split('=');
            if (parts[0] == parameterName) {
              validParam = true;
              break;
            }
          }

          if (!validParam) {
            return 'Missing required parameter "$parameterName" or invalid value for it.';
          }
        }
      } else {
        return 'Unclosed bracket found in filename. Expected closing ] but not found.';
      }
    }
  }

  return 'Valid file name with supported extension and proper parameters.';
}
