String fileNameCheck(String fileName) {
  if (fileName.isEmpty || fileName.trim().isEmpty) {
    return 'Invalid file name: empty or whitespace only';
  }

  final sanitized = fileName.replaceAll(RegExp(r'[^\w\-_\.]'), '');
  if (sanitized != fileName) {
    return "Invalid characters in file name. Only alphanumeric, underscores, dashes, periods, and spaces are allowed.";
  }

  // Check for reserved names like CON, PRN, AUX etc.
  const forbiddenNames = <String>['CON', 'PRN', 'AUX', 'NUL', 'COM1', 'COM2', 'LPT1', 'LPT2', 'LPT3'];
  if (forbiddenNames.contains(sanitized.toUpperCase())) {
    return 'File name is a system device name and cannot be used.';
  }

  // Check if the filename has an extension with more than one dot
  final parts = sanitized.split('.');
  if (parts.length > 2 && parts[0].contains('.')) {
    return 'Invalid file name: multiple dots not allowed without valid extensions.';
  }

  // Ensure that the first character isn't a period
  if (sanitized.startsWith('.')) {
    return 'Invalid file name: cannot start with a period.';
  }

  // Validate extension length
  if (parts.length >= 2) {
    final ext = parts.last;
    if (ext.length > 8) {
      return 'Invalid file name: extension too long (max 8 characters).';
    }
  }

