class FileValidator {
  static String validateFileName(String fileName) {
    if (fileName == null || fileName.trim().isEmpty) {
      return 'File name cannot be empty or null.';
    }

    // Split the file name into parts by dots
    List<String> parts = fileName.split('.');

    // Check that there is at least one dot and it's not just a single dot.
    if (parts.length < 2 || parts.join('.') == '.') {
      return 'File must have an extension. Example: "file.txt"';
    }

    // The main file name part should only contain alphanumeric and underscores
    if (!RegExp(r'^[a-zA-Z0-9_]+').hasMatch(parts[0])) {
      return 'Main file name can only contain letters, numbers, and underscores.';
    }

    // Each extension part should only contain alphanumeric, hyphens, and underscores
    for (int i = 1; i < parts.length; i++) {
      if (!RegExp(r'^[\w\-]+$').hasMatch(parts[i])) {
        return 'Extension part "${parts[i]}" has invalid characters.';
      }
    }

    return null;
  }
}

