bool simplify(String x, String n) {
  if (x == "0" && n == "1") return true;

  final List<String> xList = x.split("/");
  final List<String> nList = n.split("/");

  int xNumerator = int.parse(xList[0]);
  int xDenominator = int.parse(xList[1]);

  int nNumerator = int.parse(nList[0]);
  int nDenominator = int.parse(nList[1]);

  // Check for division by zero in the denominator of either fraction
  if (xDenominator == 0 || nDenominator == 0) {
    throw ArgumentError("Division by zero is not allowed.");
  }

  // Find greatest common divisor of numerator and denominator for both fractions
  int gcdX = _gcd(xNumerator.abs(), xDenominator.abs());
  int gcdN = _gcd(nNumerator.abs(), nDenominator.abs());

  // Simplify both fractions to their lowest terms
  xNumerator ~/= gcdX;
  xDenominator ~/= gcdX;
  nNumerator ~/= gcdN;
  nDenominator ~/= gcdN;

  // Multiply across numerators and denominators
  int newNumerator = xNumerator * nNumerator;
  int newDenominator = xDenominator * nDenominator;

  // Ensure positive denominator
  if (newDenominator < 0) {
    newNumerator *= -1;
    newDenominator *= -1;
  }

  // Check for division by zero after multiplication
  if (newDenominator == 0) {
    throw ArgumentError("Resulting denominator cannot be zero.");
  }

  // Determine whether simplified form equals 1/1 or -1/-1
  bool resultIsOneOverOne = false;
  if ((newNumerator == newDenominator)) {
    resultIsOneOverOne = true;
  } else if ((newNumerator == -newDenominator)) {
    resultIsOneOverOne = true;
  }

  return resultIsOneOverOne;
}

int _gcd(int a, int b) {
  while (b != 0) {
    var temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}
