String solve(String s) {
  if (s.isEmpty || s.length == 1) return '0';

  int n = s.length;
  List<int> digits = List<int>.filled(n, 0);

  for (int i=0; i <n; i++) {
    digits[i] = int.parse(s[i]);
  }

  int carry = 0;
  bool isLeadingZero = true;

  // Process from right to left
  for (int i=n-1; i >=0; i--) {
    int total = digits[i] + carry;

    if (digits[i] != 0 || !isLeadingZero) {
      isLeadingZero = false;
    }

    if (i < n - 1 && isLeadingZero) {
      digits[i] = 0;
    } else {
      digits[i] = total % 10;
      carry = total ~/ 10;
    }
  }

  // Handle the case where all are zeros
  if (carry > 0 || !isLeadingZero) {
    String result = '';
    for (int i=0; i <n; i++) {
      result += digits[i].toString();
    }
    return result;
  } else {
    return '0';
  }
}

